export function ProviderLogo({ provider, className }: ProviderLogoProps) {
  const logo = LOGOS[provider] ?? LOGOS.custom;
  return (
    <svg
      className={className}
      viewBox="0 0 24 24"
      width="20"
      height="20"
      role="img"
      aria-hidden="true"
      focusable="false"
    >
      <title>{logo.title}</title>
      <path d={logo.path} fill={logo.color} />
    </svg>
  );
}

/** Map registry display labels / slugs to a known third-party provider key. */
export function resolveThirdPartyProvider(
  provider: string,
): ThirdPartyProvider | null {
  const key = provider.trim().toLowerCase();
  switch (key) {
    case "openai":
      return "openai";
    case "anthropic":
      return "anthropic";
    case "gemini":
    case "google":
      return "gemini";
    case "azure":
    case "azure openai":
      return "azure";
    case "bedrock":
    case "aws bedrock":
    case "amazon bedrock":
    case "aws_bedrock":
      return "bedrock";
    case "openrouter":
      return "openrouter";
    case "nvidia":
      return "nvidia";
    case "custom":
      return "custom";
    default:
      return null;
  }
}

function isHuggingFaceProvider(provider: string): boolean {
  const key = provider.trim().toLowerCase();
  return (
    key === "hugging face" ||
    key === "huggingface" ||
    key === "hf" ||
    key === "local" ||
    key === "gguf" ||
    key === "ollama" ||
    key === "meta" ||
    key === "qwen team" ||
    key === "mistral ai"
  );
}

/** Provider mark for Model Registry rows (tooltip shows the label). */
export function RegistryProviderIcon({
  provider,
  className,
}: RegistryProviderIconProps) {
  const label = provider.trim() || "Unknown";
  const thirdParty = resolveThirdPartyProvider(label);

  return (
    <span className={`registry-provider-icon ${className ?? ""}`.trim()} title={label}>
      {thirdParty ? (
        <ProviderLogo provider={thirdParty} />
      ) : isHuggingFaceProvider(label) ? (
        <IconHuggingFace />
      ) : (
        <span className="registry-provider-icon__fallback" aria-hidden="true">
          {label.charAt(0).toUpperCase()}
        </span>
      )}
      <span className="sr-only">{label}</span>
    </span>
  );
}
